interface PaymentGateway { boolean charge(int amount); }
class Harness {
    static void report(String id, boolean ok) { System.out.println(id + ":" + (ok ? "PASS" : "FAIL")); }
    public static void main(String[] args) {
        int[] seen = {-1};
        OrderService service = new OrderService(amount -> { seen[0] = amount; return amount == 42; });
        boolean yes = service.checkout(42);
        report("delegates", seen[0] == 42);
        boolean no = service.checkout(7);
        report("returns", yes && !no);
        boolean rejected = false;
        try { new OrderService(null); } catch (NullPointerException expected) { rejected = true; }
        report("null_guard", rejected);
    }
}

