class OrderService {
    private PaymentGateway gateway;

    void setGateway(PaymentGateway gateway) {
        this.gateway = java.util.Objects.requireNonNull(gateway);
    }

    boolean checkout(int amount) {
        if (gateway == null) {
            throw new IllegalStateException("Gateway chưa được gán");
        }
        return gateway.charge(amount);
    }
}
// Field injection: một bộ lắp ráp có thể gán field trực tiếp.
// Annotation @Inject cần thư viện/container, không có sẵn trong Java SE.

class GatewaySpy implements PaymentGateway {
    int lastAmount = -1;
    public boolean charge(int amount) {
        lastAmount = amount;
        return false;
    }
}

class OrderServiceTest {
    public static void main(String[] args) {
        GatewaySpy spy = new GatewaySpy();
        OrderService service = new OrderService(spy);
        boolean result = service.checkout(100);
        if (result || spy.lastAmount != 100) {
            throw new AssertionError("Sai delegation hoặc kết quả");
        }
    }
}
// Dùng PaymentGateway và OrderService ở nút Constructor Injection.

class DemoGateway implements PaymentGateway {
    public boolean charge(int amount) {
        return amount > 0; // Chỉ minh họa, không thanh toán thật.
    }
}

class Application {
    public static void main(String[] args) {
        PaymentGateway gateway = new DemoGateway();
        OrderService orders = new OrderService(gateway);
        System.out.println(orders.checkout(100));
    }
}
// Dùng PaymentGateway và OrderService từ nút Constructor Injection.
// main chọn implementation; OrderService chỉ xử lý đơn hàng.
